function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(10, 10, W-20, H-20);
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(20, H-50);
  ctx.lineTo(20, H-20);
  ctx.lineTo(W-20, H-20);
  ctx.lineTo(W-20, H-50);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Workbench', 30, H-40);
  ctx.beginPath();
  ctx.arc(W/2, 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '15px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Light', W/2, 50);
  ctx.beginPath();
  ctx.moveTo(50, 100);
  ctx.lineTo(50 + 30 * Math.sin(t), 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-50, 100);
  ctx.lineTo(W-50 + 30 * Math.sin(t + Math.PI), 100);
  ctx.stroke();
  ctx.restore();
}
